char field[H][W + 1];
int visited[H][W];
int qy[H * W], qx[H * W];
int cells_y[H * W], cells_x[H * W];

int in_bounds(int y, int x) {
    return (0 <= y && y < H && 0 <= x && x < W);
}

void apply_gravity() {
    for (int x = 0; x < W; x++) {
        int write = H - 1;
        for (int y = H - 1; y >= 0; y--) {
            if (field[y][x] != '.') {
                char c = field[y][x];
                field[y][x] = '.';
                field[write][x] = c;
                write--;
            }
        }
        while (write >= 0) {
            field[write][x] = '.';
            write--;
        }
    }
}

int step_once() {
    memset(visited, 0, sizeof(visited));
    int to_remove[H][W];
    memset(to_remove, 0, sizeof(to_remove));

    int any = 0;
    int dy[4] = {-1, 1, 0, 0};
    int dx[4] = {0, 0, -1, 1};

    for (int sy = 0; sy < H; sy++) {
        for (int sx = 0; sx < W; sx++) {
            if (field[sy][sx] == '.' || visited[sy][sx]) continue;

            char color = field[sy][sx];
            int head = 0, tail = 0, cnt = 0;

            visited[sy][sx] = 1;
            qy[tail] = sy; qx[tail] = sx; tail++;

            while (head < tail) {
                int y = qy[head], x = qx[head];
                head++;

                cells_y[cnt] = y;
                cells_x[cnt] = x;
                cnt++;

                for (int dir = 0; dir < 4; dir++) {
                    int ny = y + dy[dir];
                    int nx = x + dx[dir];
                    if (!in_bounds(ny, nx)) continue;
                    if (visited[ny][nx]) continue;
                    if (field[ny][nx] != color) continue;
                    visited[ny][nx] = 1;
                    qy[tail] = ny; qx[tail] = nx; tail++;
                }
            }

            if (cnt >= 4) {
                any = 1;
                for (int i = 0; i < cnt; i++) {
                    to_remove[cells_y[i]][cells_x[i]] = 1;
                }
            }
        }
    }

    if (!any) return 0;

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (to_remove[y][x]) field[y][x] = '.';
        }
    }

    apply_gravity();
    return 1;
}

