public class FallingBlocks {
    static final int H = 12;
    static final int W = 6;
    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int datasets = sc.nextInt();
        sc.nextLine(); // consume newline

        for (int d = 0; d < datasets; d++) {
            char[][] grid = new char[H][W];
            for (int i = 0; i < H; i++) {
                String line = sc.nextLine();
                for (int j = 0; j < W; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            int chains = 0;
            while (true) {
                boolean[][] visited = new boolean[H][W];
                List<int[]> toRemove = new ArrayList<>();

                // Find all groups of 4 or more same non-blocking blocks
                for (int r = 0; r < H; r++) {
                    for (int c = 0; c < W; c++) {
                        if (grid[r][c] != '.' && grid[r][c] != 'X' && !visited[r][c]) {
                            List<int[]> group = new ArrayList<>();
                            char color = grid[r][c];
                            Queue<int[]> q = new LinkedList<>();
                            q.add(new int[]{r, c});
                            visited[r][c] = true;

                            while (!q.isEmpty()) {
                                int[] cur = q.poll();
                                group.add(cur);

                                for (int k = 0; k < 4; k++) {
                                    int nr = cur[0] + DR[k];
                                    int nc = cur[1] + DC[k];
                                    if (nr >= 0 && nr < H && nc >= 0 && nc < W 
                                        && !visited[nr][nc] && grid[nr][nc] == color) {
                                        visited[nr][nc] = true;
                                        q.add(new int[]{nr, nc});
                                    }
                                }
                            }

                            if (group.size() >= 4) {
                                toRemove.addAll(group);
                            }
                        }
                    }
                }

                if (toRemove.isEmpty()) {
                    break;
                }
                chains++;

                // Remove blocks
                for (int[] pos : toRemove) {
                    grid[pos[0]][pos[1]] = '.';
                }

                // Apply gravity
                for (int c = 0; c < W; c++) {
                    int writeRow = H - 1;
                    for (int r = H - 1; r >= 0; r--) {
                        if (grid[r][c] != '.') {
                            grid[writeRow][c] = grid[r][c];
                            if (writeRow != r) {
                                grid[r][c] = '.';
                            }
                            writeRow--;
                        }
                    }
                }
            }

            System.out.println(chains);
        }
        sc.close();
    }
