        while (T-- > 0) {
            grid = new char[ROWS][COLS];
            for (int i = 0; i < ROWS; i++) {
                String line = sc.next();
                for (int j = 0; j < COLS; j++) grid[i][j] = line.charAt(j);
            }
            System.out.println(simulate());
        }
    }

    static int simulate() {
        int chains = 0;
        while (true) {
            boolean removed = step();
            if (!removed) break;
            chains++;
            applyGravity();
        }
        return chains;
    }

    static boolean step() {
        boolean[][] toRemove = new boolean[ROWS][COLS];
        boolean anyRemoved = false;
        for (int i = 0; i < ROWS; i++) {
            for (int j = 0; j < COLS; j++) {
                char c = grid[i][j];
                if (c == '.' || c == 'X') continue;
                // BFS
                List<int[]> comp = new ArrayList<>();
                boolean[][] vis = new boolean[ROWS][COLS];
                Queue<int[]> q = new LinkedList<>();
                q.add(new int[]{i,j}); vis[i][j] = true;
                while (!q.isEmpty()) {
                    int[] cur = q.poll(); comp.add(cur);
                    for (int d = 0; d < 4; d++) {
                        int nr = cur[0]+dr[d], nc = cur[1]+dc[d];
                        if (nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&!vis[nr][nc]&&grid[nr][nc]==c) {
                            vis[nr][nc]=true; q.add(new int[]{nr,nc});
                        }
                    }
                }
                if (comp.size() >= 4) {
                    anyRemoved = true;
                    for (int[] p : comp) toRemove[p[0]][p[1]] = true;
                }
            }
        }
        if (!anyRemoved) return false;
        // Remove adjacent blocking blocks
        for (int i = 0; i < ROWS; i++)
            for (int j = 0; j < COLS; j++)
                if (toRemove[i][j])
                    for (int d = 0; d < 4; d++) {
                        int nr=i+dr[d], nc=j+dc[d];
                        if (nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&grid[nr][nc]=='X') toRemove[nr][nc]=true;
                    }
        for (int i = 0; i < ROWS; i++)
            for (int j = 0; j < COLS; j++)
                if (toRemove[i][j]) grid[i][j] = '.';
        return true;
    }

    static void applyGravity() {
        for (int j = 0; j < COLS; j++) {
            int empty = ROWS-1;
            for (int i = ROWS-1; i >= 0; i--) {
                if (grid[i][j] != '.') { grid[empty][j]=grid[i][j]; if(empty!=i) grid[i][j]='.'; empty--; }
            }
            while (empty >= 0) { grid[empty][j]='.'; empty--; }
        }
    }
}

