public class Main {
    static final int H = 12;
    static final int W = 6;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;
        int T = Integer.parseInt(first.trim());

        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            char[][] board = new char[H][W];
            for (int i = 0; i < H; i++) {
                String s = br.readLine();
                while (s != null && s.length() < W) s += " ";
                board[i] = s.toCharArray();
            }

            int chains = solve(board);
            out.append(chains).append('\n');
        }

        System.out.print(out.toString());
    }

    static int solve(char[][] board) {
        int chainCount = 0;

        while (true) {
            boolean[][] visited = new boolean[H][W];
            boolean[][] remove = new boolean[H][W];
            boolean any = false;

            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    char ch = board[r][c];
                    if (ch == '.' || ch == 'O' || visited[r][c]) continue;

                    List<int[]> comp = new ArrayList<>();
                    bfs(board, r, c, ch, visited, comp);

                    if (comp.size() >= 4) {
                        any = true;
                        for (int[] p : comp) remove[p[0]][p[1]] = true;
                    }
                }
            }

            if (!any) break;

            // Remove matched colored blocks and adjacent blocking blocks
            boolean[][] extraRemove = new boolean[H][W];
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    if (!remove[r][c]) continue;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (0 <= nr && nr < H && 0 <= nc && nc < W && board[nr][nc] == 'O') {
                            extraRemove[nr][nc] = true;
                        }
                    }
                }
            }

            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    if (remove[r][c] || extraRemove[r][c]) board[r][c] = '.';
                }
            }

            applyGravity(board);
            chainCount++;
        }

        return chainCount;
    }

    static void bfs(char[][] board, int sr, int sc, char color, boolean[][] visited, List<int[]> comp) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            comp.add(cur);

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (0 <= nr && nr < H && 0 <= nc && nc < W && !visited[nr][nc] && board[nr][nc] == color) {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }

    static void applyGravity(char[][] board) {
        for (int c = 0; c < W; c++) {
            int write = H - 1;
            for (int r = H - 1; r >= 0; r--) {
                if (board[r][c] != '.') {
                    char ch = board[r][c];
                    board[r][c] = '.';
                    board[write][c] = ch;
                    write--;
                }
            }
        }
    }
