import sys
from collections import deque

def solve(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def get_connected(r, c, color):
        visited = set()
        queue = deque([(r, c)])
        visited.add((r, c))
        while queue:
            nr, nc = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                rr, cc = nr+dr, nc+dc
                if 0 <= rr < rows and 0 <= cc < cols and (rr,cc) not in visited and grid[rr][cc] == color:
                    visited.add((rr,cc))
                    queue.append((rr,cc))
        return visited

    def apply_gravity():
        for c in range(cols):
            col = [grid[r][c] for r in range(rows) if grid[r][c] != '.']
            # fill from bottom
            for r in range(rows-1, -1, -1):
                idx = rows - 1 - r
                if idx < len(col):
                    grid[r][c] = col[-(idx+1)]
                else:
                    grid[r][c] = '.'

    chains = 0
    while True:
        # Find all groups of 4+ same color (not '.' or blocking)
        visited_all = set()
        to_remove = set()
        for r in range(rows):
            for c in range(cols):
                color = grid[r][c]
                if color == '.' or color == 'X' or (r,c) in visited_all:
                    continue
                group = get_connected(r, c, color)
                visited_all |= group
                if len(group) >= 4:
                    to_remove |= group

        if not to_remove:
            break

        chains += 1
        for r, c in to_remove:
            grid[r][c] = '.'

        apply_gravity()

    return chains

