int h, w;
vector<string> grid;

// Find connected components of same color
void dfs(int y, int x, char color, vector<vector<bool>>& visited, vector<pair<int,int>>& component) {
    if (y < 0 || y >= h || x < 0 || x >= w) return;
    if (visited[y][x] || grid[y][x] != color) return;
    if (grid[y][x] == '0') return;  // empty space

    visited[y][x] = true;
    component.push_back({y, x});

    for (int i = 0; i < 4; i++) {
        dfs(y + dy[i], x + dx[i], color, visited, component);
    }
}

// Remove blocks and let them fall
bool removeAndFall() {
    vector<vector<bool>> visited(h, vector<bool>(w, false));
    bool removed = false;

    // Find all components of 4+ blocks
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (!visited[i][j] && grid[i][j] != '0') {
                vector<pair<int,int>> component;
                dfs(i, j, grid[i][j], visited, component);

                if (component.size() >= 4) {
                    removed = true;
                    for (auto& p : component) {
                        grid[p.first][p.second] = '0';
                    }
                }
            }
        }
    }

    if (!removed) return false;

    // Apply gravity
    for (int j = 0; j < w; j++) {
        int writePos = h - 1;
        for (int i = h - 1; i >= 0; i--) {
            if (grid[i][j] != '0') {
                grid[writePos][j] = grid[i][j];
                if (writePos != i) {
                    grid[i][j] = '0';
                }
                writePos--;
            }
        }
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    while (n--) {
        cin >> h >> w;
        grid.resize(h);
        for (int i = 0; i < h; i++) {
            cin >> grid[i];
        }

        int chains = 0;
        while (removeAndFall()) {
            chains++;
        }

        cout << chains << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int R, C;
char grid[13][7];
int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

bool applyGravity() {
    bool moved = false;
    for (int c = 0; c < C; c++) {
        int write = R-1;
        for (int r = R-1; r >= 0; r--) {
            if (grid[r][c] != '.') {
                if (write != r) { grid[write][c] = grid[r][c]; grid[r][c] = '.'; moved = true; }
                write--;
            }
        }
    }
    return moved;
}

bool step() {
    // Find connected components of colored blocks (not blocking 'X')
    bool visited[13][7] = {};
    bool toDelete[13][7] = {};
    bool anyDelete = false;

    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            if (visited[r][c] || grid[r][c] == '.' || grid[r][c] == 'X') continue;
            // BFS
            vector<pair<int,int>> comp;
            queue<pair<int,int>> q;
            q.push({r,c}); visited[r][c] = true;
            while (!q.empty()) {
                auto [x,y] = q.front(); q.pop();
                comp.push_back({x,y});
                for (int d = 0; d < 4; d++) {
                    int nx = x+dx[d], ny = y+dy[d];
                    if (nx>=0&&nx<R&&ny>=0&&ny<C&&!visited[nx][ny]&&grid[nx][ny]==grid[r][c]) {
                        visited[nx][ny]=true; q.push({nx,ny});
                    }
                }
            }
            if ((int)comp.size() >= 4) {
                for (auto [x,y]: comp) toDelete[x][y] = true;
                anyDelete = true;
            }
        }
    }
    if (!anyDelete) return false;
    // Delete blocking blocks adjacent to deleted colored blocks
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (toDelete[r][c])
                for (int d = 0; d < 4; d++) {
                    int nr=r+dx[d], nc=c+dy[d];
                    if (nr>=0&&nr<R&&nc>=0&&nc<C&&grid[nr][nc]=='X') toDelete[nr][nc]=true;
                }
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (toDelete[r][c]) grid[r][c]='.';
    applyGravity();
    return true;
}

int main(){
    int T; cin>>T;
    R=12; C=6;
    while(T--){
        for(int r=0;r<R;r++) cin>>grid[r];
        int chains=0;
        while(step()) chains++;
        cout<<chains<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

static const int H = 12;
static const int W = 6;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    while (N--) {
        vector<string> g(H);
        for (int i = 0; i < H; ++i) cin >> g[i];

        int chains = 0;

        while (true) {
            vector<vector<int>> vis(H, vector<int>(W, 0));
            vector<pair<int,int>> toErase;

            for (int i = 0; i < H; ++i) {
                for (int j = 0; j < W; ++j) {
                    char c = g[i][j];
                    if (c == '.' || c == 'O' || vis[i][j]) continue; // '.' empty, 'O' blocking block

                    queue<pair<int,int>> q;
                    vector<pair<int,int>> comp;
                    q.push({i, j});
                    vis[i][j] = 1;
                    comp.push_back({i, j});

                    const int dx[4] = {-1, 1, 0, 0};
                    const int dy[4] = {0, 0, -1, 1};

                    while (!q.empty()) {
                        auto [x, y] = q.front();
                        q.pop();
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                            if (vis[nx][ny]) continue;
                            if (g[nx][ny] != c) continue;
                            vis[nx][ny] = 1;
                            q.push({nx, ny});
                            comp.push_back({nx, ny});
                        }
                    }

                    if ((int)comp.size() >= 4) {
                        for (auto &p : comp) toErase.push_back(p);
                    }
                }
            }

            if (toErase.empty()) break;

            for (auto &[x, y] : toErase) g[x][y] = '.';

            // gravity
            for (int col = 0; col < W; ++col) {
                int write = H - 1;
                for (int row = H - 1; row >= 0; --row) {
                    if (g[row][col] != '.') {
                        g[write][col] = g[row][col];
                        if (write != row) g[row][col] = '.';
                        --write;
                    }
                }
                while (write >= 0) {
                    g[write][col] = '.';
                    --write;
                }
            }

            ++chains;
        }

        cout << chains << '\n';
    }

    return 0;
}
